((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
globalThis.KENGURU_GRADES_7_8 = [{"id":"2007-9-10","year":2007,"grades":[9,10],"label":"9–10 классы","tasksUrl":"assets/kenguru/kenguru_2007_class_9-10.pdf","answersUrl":"assets/kenguru/kenguru_2007_answers.pdf","solutionUrl":null,"answerLetters":"ABCDE","cards":[{"number":1,"title":"Буквы слова МАТЕМАТИКА","question":"В слове МАТЕМАТИКА стерли 6 букв (возможно, среди них были одинаковые). Оставшиеся буквы переписали в обратном порядке. Что не могло получиться?","options":[{"text":"КАМА"},{"text":"КИМА"},{"text":"АТЕМ"},{"text":"ТЕМА"},{"text":"ТАЕТ"}],"condition":null,"answer":3,"points":3,"review":[{"title":"Решение","text":"Обратим порядок букв в каждом варианте и посмотрим, можно ли получить их вычёркиванием из МАТЕМАТИКА. Для A, B, C и E нужные буквы стоят соответственно на местах (2, 5, 6, 9), (2, 5, 8, 9), (1, 4, 7, 10) и (3, 4, 6, 7)."},{"title":"Ответ","text":"В D обратная запись АМЕТ. После первой А и следующей М буквы Е уже нет. Поэтому ТЕМА не получится."}],"keyNote":null},{"number":2,"title":"Нули и единицы в квадрате","question":"В клетках квадрата 4 × 4 написали цифры 0 и 1 так, что в каждой строке и каждом столбце оказалось по 2 единицы и по 2 нуля. Потом некоторые цифры стерли, а две – обозначили буквами X и Y. Чему равны X и Y?","options":[{"text":"X = Y = 1"},{"text":"X = 1, Y = 0"},{"text":"X = 0, Y = 1"},{"text":"X = Y = 0"},{"text":"невозможно определить"}],"condition":{"src":"assets/grades-9-10/2007/task-02.svg","width":185,"height":184,"alt":"В первой строке единицы в первом и третьем столбцах. Во второй строке единица в третьем столбце. В третьей строке X во втором столбце, 0 в четвёртом. В четвёртой строке Y во втором столбце."},"answer":0,"points":3,"review":[{"title":"Решение","text":"В первой строке уже две единицы, значит, её второе место — ноль. В третьем столбце две единицы стоят в первых двух строках, так что в третьей и четвёртой строках там нули."},{"title":"Ответ","text":"В третьей строке последние две клетки нули, поэтому X = 1 и первая клетка тоже 1. В первом столбце теперь две единицы, значит, в четвёртой строке первая и третья позиции нули. Получаем Y = 1."}],"keyNote":null},{"number":3,"title":"Числа 27 и 3","question":"Чем является число 27 для числа 3?","options":[{"text":"квадратом"},{"text":"треугольником"},{"text":"кругом"},{"text":"кубом"},{"text":"шаром"}],"condition":null,"answer":3,"points":3,"review":[{"title":"Решение","text":"Куб числа получается умножением трёх одинаковых множителей."},{"title":"Ответ","text":"Имеем 27 = 3 × 3 × 3. Это куб числа 3."}],"keyNote":null},{"number":4,"title":"Площадь треугольника AEF","question":"В треугольнике ABC точка D – середина AB, E – середина DB, F – середина BC. Если площадь треугольника ABC равна 96, то площадь треугольника AEF равна","options":[{"text":"16"},{"text":"24"},{"text":"32"},{"text":"36"},{"text":"48"}],"condition":{"src":"assets/grades-9-10/2007/task-04.svg","width":347,"height":216,"alt":"На горизонтальном основании последовательно A, D, E и B. Вершина C вверху, F на стороне BC. Треугольник AEF закрашен."},"answer":3,"points":3,"review":[{"title":"Решение","text":"Основание AE составляет 3/4 от AB, поскольку D и E — последовательные середины. Высота из F к AB составляет половину высоты из C."},{"title":"Ответ","text":"Площадь AEF равна (3/4) × (1/2) × 96 = 36."}],"keyNote":null},{"number":5,"title":"Возведение в квадрат","question":"При возведении в квадрат","options":[{"text":"число всегда увеличивается"},{"text":"число всегда уменьшается"},{"text":"число всегда изменяется"},{"text":"изменяются все числа, кроме одного"},{"text":"изменяются все числа, кроме двух"}],"condition":null,"answer":4,"points":3,"review":[{"title":"Решение","text":"Число x сохраняется при возведении в квадрат, когда x² = x."},{"title":"Ответ","text":"Получаем x(x − 1) = 0. Подходят ровно два числа, 0 и 1."}],"keyNote":null},{"number":6,"title":"Операция с корнем","question":"Пусть x ∗ y = x√y. Чему равно (√18 ∗ 2) ∗ 3?","options":[{"text":"6√2"},{"text":"6"},{"text":"6√3"},{"text":"18√2"},{"text":"18"}],"condition":null,"answer":2,"points":3,"review":[{"title":"Решение","text":"Сначала √18 ∗ 2 = √18 × √2 = √36 = 6."},{"title":"Ответ","text":"Затем 6 ∗ 3 = 6√3."}],"keyNote":null},{"number":7,"title":"Примета о крокодилах","question":"Народная примета племени Уа-Уа гласит: «Если крокодилы едят быстро, то скоро будет дождь». Это означает, что","options":[{"text":"если дождя не ожидается, а крокодилы едят, то они едят не быстро"},{"text":"если в местности нет крокодилов, то там не бывает дождя"},{"text":"если собирается дождь, то крокодилы едят быстро"},{"text":"если крокодилы едят медленно, то дождя не будет"},{"text":"если крокодилы воздерживаются от еды, то дождя не будет"}],"condition":null,"answer":0,"points":3,"review":[{"title":"Решение","text":"Правило означает, что быстрая еда крокодилов влечёт дождь. Если дождя не ожидается, крокодилы не могут есть быстро."},{"title":"Ответ","text":"Если они всё-таки едят, то делают это не быстро. Обратные утверждения правило не обещает."}],"keyNote":null},{"number":8,"title":"Число-гигант","question":"Число 10¹⁰⁰ назовем гигантом. Чему равно число 1000¹⁰⁰?","options":[{"text":"100 гигантов"},{"text":"3 гиганта"},{"text":"гигант³"},{"text":"гигант²"},{"text":"гигант в степени гигант"}],"condition":null,"answer":2,"points":3,"review":[{"title":"Решение","text":"Поскольку 1000 = 10³, получаем 1000¹⁰⁰ = 10³⁰⁰."},{"title":"Ответ","text":"А 10³⁰⁰ = (10¹⁰⁰)³, то есть куб гиганта."}],"keyNote":null},{"number":9,"title":"Квадрат и треугольник","question":"ABCD – квадрат, а CDF – правильный треугольник. Чему равен угол BAF?","options":[{"text":"60°"},{"text":"75°"},{"text":"85°"},{"text":"67°30′"},{"text":"другой ответ"}],"condition":{"src":"assets/grades-9-10/2007/task-09.svg","width":287,"height":196,"alt":"У квадрата A внизу слева, B вверху слева, C вверху справа, D внизу справа. Справа от стороны CD вершина F правильного треугольника. Проведён отрезок AF. Искомый угол отмечен у A."},"answer":1,"points":3,"review":[{"title":"Решение","text":"Стороны AD и DF равны. Угол между DA и DC равен 90°, а между DC и DF — 60°, поэтому ∠ADF = 150°."},{"title":"Ответ","text":"Угол DAF в равнобедренном треугольнике равен 15°. Тогда ∠BAF = 90° − 15° = 75°."}],"keyNote":null},{"number":10,"title":"Сумма цифр квадрата","question":"Натуральные числа, большие 2007, возвели в квадрат и у каждого квадрата вычислили сумму цифр. Самая маленькая из этих сумм равна","options":[{"text":"27"},{"text":"19"},{"text":"2007"},{"text":"1"},{"text":"другой ответ"}],"condition":null,"answer":3,"points":3,"review":[{"title":"Решение","text":"Сумма цифр положительного числа не меньше 1."},{"title":"Ответ","text":"Возьмём 10 000, которое больше 2007. Его квадрат — единица с восемью нулями, у него сумма цифр 1."}],"keyNote":null},{"number":11,"title":"Разность произведений","question":"Чему равно число 9999994 · 9999995 − 9999990 · 9999999?","options":[{"text":"0"},{"text":"20"},{"text":"180"},{"text":"990"},{"text":"9999990"}],"condition":null,"answer":1,"points":4,"review":[{"title":"Решение","text":"Пусть n = 9 999 990. Тогда выражение равно (n + 4)(n + 5) − n(n + 9)."},{"title":"Ответ","text":"В первом произведении получаем n² + 9n + 20, во втором n² + 9n. Разность 20."}],"keyNote":null},{"number":12,"title":"Радиус окружности","question":"Прямоугольный треугольник таков, что длина его гипотенузы равна сумме квадратов длин его катетов. Чему равен радиус окружности, описанной около этого треугольника?","options":[{"text":"1"},{"text":"1/2"},{"text":"1/3"},{"text":"такого треугольника не существует"},{"text":"невозможно определить"}],"condition":null,"answer":1,"points":4,"review":[{"title":"Решение","text":"По условию гипотенуза c равна a² + b². По теореме Пифагора та же сумма равна c²."},{"title":"Ответ","text":"Из c = c² и c > 0 получаем c = 1. Радиус описанной окружности половина гипотенузы, то есть 1/2."}],"keyNote":null},{"number":13,"title":"Центры трёх окружностей","question":"Каждая из трех окружностей на чертеже касается двух других. Радиус большей окружности равен 6. Какова сумма расстояний между центрами?","options":[{"text":"12"},{"text":"9"},{"text":"6"},{"text":"3"},{"text":"невозможно определить"}],"condition":{"src":"assets/grades-9-10/2007/task-13.svg","width":222,"height":220,"alt":"В большой окружности две меньшие, они касаются большой окружности изнутри и друг друга снаружи. Центры показаны точками и соединены отрезками."},"answer":0,"points":4,"review":[{"title":"Решение","text":"Если радиусы малых окружностей r и s, расстояние между их центрами равно r + s."},{"title":"Ответ","text":"Расстояния от большого центра равны 6 − r и 6 − s. Сумма трёх расстояний 12."}],"keyNote":null},{"number":14,"title":"Квадрат и куб из числа N","question":"Пусть N – наименьшее из натуральных чисел, обладающих следующим свойством: 10N является квадратом некоторого натурального числа, а 6N – кубом. Чему равна сумма первой и последней цифр числа N?","options":[{"text":"3"},{"text":"5"},{"text":"6"},{"text":"8"},{"text":"13"}],"condition":null,"answer":0,"points":4,"review":[{"title":"Решение","text":"Обозначим показатели при простых 2, 3 и 5 в N через a, b и c. Для квадрата 10N показатели a + 1 и c + 1 должны быть чётными, а b чётным."},{"title":"Проверка","text":"Для куба 6N числа a + 1, b + 1 и c должны делиться на 3. Минимум дают a = 5, b = 2 и c = 3."},{"title":"Ответ","text":"Тогда N = 2⁵·3²·5³ = 36 000. Первая и последняя цифры дают 3 + 0 = 3."}],"keyNote":null},{"number":15,"title":"Связь корней уравнений","question":"Пусть число m – один из корней уравнения x³ + 1 = 2007x. Какое из чисел наверняка является корнем уравнения x³ + 1 = 2007x²?","options":[{"text":"8m/5"},{"text":"5m/2"},{"text":"m²"},{"text":"1/m"},{"text":"m + 1"}],"condition":null,"answer":3,"points":4,"review":[{"title":"Решение","text":"Корень m не равен нулю. Разделим равенство m³ + 1 = 2007m на m³."},{"title":"Ответ","text":"Получаем 1 + (1/m)³ = 2007(1/m)². Это означает, что 1/m — корень второго уравнения."}],"keyNote":null},{"number":16,"title":"Меткость Васи","question":"Вася учится стрелять в тире. Месяц назад, на первом занятии, он попал 40 раз из 100. Сегодня, после месяца тренировок, он сделал 200 выстрелов и обнаружил, что его меткость (то есть доля удачных выстрелов) повысилась на 80%. Сколько раз он попал сегодня?","options":[{"text":"120"},{"text":"140"},{"text":"144"},{"text":"160"},{"text":"240"}],"condition":null,"answer":2,"points":4,"review":[{"title":"Решение","text":"Начальная меткость равна 40 %. Рост на 80 % означает умножение этой доли на 1,8."},{"title":"Ответ","text":"Сегодня меткость 0,4 × 1,8 = 0,72. Из 200 выстрелов удачны 144."}],"keyNote":null},{"number":17,"title":"Вершины, рёбра и грани","question":"Маша сложила три числа: количество вершин, количество ребер и количество граней некоторой пирамиды. Какой результат она могла получить?","options":[{"text":"28"},{"text":"29"},{"text":"30"},{"text":"31"},{"text":"32"}],"condition":null,"answer":2,"points":4,"review":[{"title":"Решение","text":"При основании с n вершинами пирамида имеет n + 1 вершин, 2n рёбер и n + 1 граней."},{"title":"Ответ","text":"Сумма равна 4n + 2. Среди предложенных значений только 30 имеет такой вид, это случай n = 7."}],"keyNote":null},{"number":18,"title":"Два строгих неравенства","question":"Числа a и b таковы, что a > 1/b и 1/a > b. Тогда","options":[{"text":"ab > 1"},{"text":"a < 0"},{"text":"b > a"},{"text":"b < 0"},{"text":"такого не бывает"}],"condition":null,"answer":3,"points":4,"review":[{"title":"Решение","text":"Предположим, что b положительно. Тогда a > 1/b > 0, поэтому обе части каждого неравенства можно умножить на соответствующий положительный знаменатель."},{"title":"Ответ","text":"Первое даёт ab > 1, а второе ab < 1. Это противоречие. b не может быть нулём, так что b < 0."}],"keyNote":null},{"number":19,"title":"Квадраты цифр и суммы","question":"Для некоторых трехзначных чисел квадрат суммы цифр равен сумме квадратов этих цифр. Сколько таких чисел?","options":[{"text":"0"},{"text":"9"},{"text":"10"},{"text":"1"},{"text":"90"}],"condition":null,"answer":1,"points":4,"review":[{"title":"Решение","text":"Для цифр a, b и c разность квадрата суммы и суммы квадратов равна 2(ab + ac + bc). Все произведения неотрицательны."},{"title":"Ответ","text":"Цифра сотен a положительна, поэтому равенство возможно только при b = c = 0. Подходят девять чисел от 100 до 900."}],"keyNote":null},{"number":20,"title":"Меньшее из двух значений","question":"Пусть f(x) – это меньшее из чисел 2x и 6 − x. Какое самое большое значение принимает величина f(x)?","options":[{"text":"2"},{"text":"4"},{"text":"6"},{"text":"8"},{"text":"наибольшего значения нет"}],"condition":null,"answer":1,"points":4,"review":[{"title":"Решение","text":"Прямые 2x и 6 − x пересекаются при x = 2, значение обеих равно 4."},{"title":"Ответ","text":"Левее x = 2 меньшим служит возрастающее 2x, правее — убывающее 6 − x. Максимум меньшего значения равен 4."}],"keyNote":null},{"number":21,"title":"Угол против стороны c","question":"a, b, c – стороны треугольника. Известно, что (a + b + c) · (a + b − c) = 3ab. Какой угол лежит против стороны c?","options":[{"text":"150°"},{"text":"30°"},{"text":"45°"},{"text":"60°"},{"text":"90°"}],"condition":null,"answer":3,"points":5,"review":[{"title":"Решение","text":"Раскроем произведение разности и суммы. Получим (a + b)² − c² = 3ab, откуда c² = a² + b² − ab."},{"title":"Ответ","text":"По теореме косинусов косинус угла напротив c равен 1/2. Это угол 60°."}],"keyNote":null},{"number":22,"title":"Ожерелья Кощея","question":"В шкатулке у Кощея Бессмертного лежит несколько одинаковых ожерелий (более одного). Он знает, что общее число бусинок на ожерельях в шкатулке меньше 300 и больше 200. Если бы Кощей знал это число точно, то, подумав, он мог бы назвать точное количество ожерелий, не открывая шкатулки. Сколько ожерелий в шкатулке?","options":[{"text":"16"},{"text":"17"},{"text":"19"},{"text":"25"},{"text":"невозможно определить"}],"condition":null,"answer":1,"points":5,"review":[{"title":"Решение","text":"Для полного числа бусин N возможное число ожерелий — делитель N. И ожерелий, и бусин в каждом больше одного. Чтобы делитель был только один, N должен быть квадратом простого: разные простые множители дали бы два делителя, а более высокая степень дала бы p и p²."},{"title":"Ответ","text":"Из квадратов простых только 17² = 289 лежит между 200 и 300. Значит, ожерелий 17."}],"keyNote":null,"questionNote":"В каждом ожерелье больше одной бусины."},{"number":23,"title":"Многоугольник на кубе","question":"Какое наибольшее количество вершин может быть у выпуклого многоугольника, если эти вершины лежат на поверхности куба, но сам многоугольник не лежит ни на какой грани куба?","options":[{"text":"4"},{"text":"6"},{"text":"8"},{"text":"12"},{"text":"18"}],"condition":null,"answer":3,"points":5,"review":[{"title":"Решение","text":"Плоскость многоугольника пересекает куб по сечению с числом сторон не больше шести, по одной стороне от каждой грани. Вершины многоугольника лежат на границе этого сечения. На одной стороне сечения может быть не больше двух вершин, иначе одна из них была бы внутри отрезка."},{"title":"Ответ","text":"Сечение, перпендикулярное пространственной диагонали через центр, является шестиугольником. Отметим по две точки внутри каждой его стороны близко к обоим концам. Получим выпуклый двенадцатиугольник."}],"keyNote":null},{"number":24,"title":"Собака на верёвке","question":"Дом имеет размеры 4 м × 6 м. Собака, привязанная к углу дома 10-метровой веревкой, бегает по двору. Какова площадь участка, доступного собаке?","options":[{"text":"100π"},{"text":"100π − 24"},{"text":"76π"},{"text":"88π"},{"text":"другой ответ"}],"condition":{"src":"assets/grades-9-10/2007/task-24.svg","width":487,"height":295,"pixelWidth":162,"pixelHeight":98,"alt":"Прямоугольный дом. Передняя сторона подписана 6 м, боковая — 4 м. Из дальнего угла короткой стороны к собаке тянется верёвка с подписью 10 м."},"answer":3,"points":5,"review":[{"title":"Решение","text":"С угла дома собака достаёт до трёх четвертей круга радиуса 10. За углами верёвка дополнительно огибает стороны длины 4 м и 6 м."},{"title":"Ответ","text":"Остаётся соответственно 6 и 4 м верёвки, получаются ещё две четверти круга. Дальний угол расходует все 10 м. Площадь равна (3 × 100 + 36 + 16)π/4 = 88π м²."}],"keyNote":null},{"number":25,"title":"Косинусы степеней десяти","question":"Сколько отрицательных чисел среди членов последовательности cos 1°, cos 10°, cos 100°, cos 1000°, …?","options":[{"text":"1"},{"text":"2"},{"text":"10"},{"text":"100"},{"text":"бесконечно много"}],"condition":null,"answer":0,"points":5,"review":[{"title":"Решение","text":"Косинусы 1° и 10° положительны, а косинус 100° отрицателен. У 1000° тот же косинус, что у 280°."},{"title":"Ответ","text":"При умножении 280 на 10 остаток по модулю 360 снова 280. Значит, все дальнейшие косинусы равны cos 280° > 0. Отрицательный ровно один."}],"keyNote":null},{"number":26,"title":"Число с особым кратным","question":"Назовем натуральное число N особым, если можно подобрать такое натуральное число M, что в записи произведения M · N все цифры одинаковы. Какое из следующих чисел не особое?","options":[{"text":"13"},{"text":"14"},{"text":"15"},{"text":"16"},{"text":"18"}],"condition":null,"answer":3,"points":5,"review":[{"title":"Решение","text":"Числа 111111, 222222, 555 и 666 кратны соответственно 13, 14, 15 и 18. Все эти N особые."},{"title":"Ответ","text":"Число из одинаковых цифр равно d × 11…1, где d от 1 до 9. Множитель 11…1 нечётен. Для делимости на 16 сама цифра d должна делиться на 16, чего не бывает."}],"keyNote":null},{"number":27,"title":"Уравнения с функцией f","question":"Пусть f – такая функция, что уравнение f(x) = x имеет ровно один корень. Какое из следующих уравнений может иметь более двух корней?","options":[{"text":"(1/3)f(3x) = x"},{"text":"f(f(x) + 1) = f(x) + 1"},{"text":"f(x²) = x²"},{"text":"∛(f(x³ − 1) + 1) = x"},{"text":"никакое"}],"condition":null,"answer":1,"points":5,"review":[{"title":"Решение","text":"Если единственная неподвижная точка f равна t, то в A необходимо 3x = t, в C — x² = t, в D — x³ − 1 = t. Каждое из этих уравнений имеет не больше двух корней."},{"title":"Ответ","text":"Для B нужно f(x) + 1 = t. Пусть f(0) = f(−1) = 0, а на всех остальных x положим f(x) = −1. Единственная неподвижная точка — 0, но f(x) + 1 = 0 для всех x, кроме 0 и −1. Подходит B."}],"keyNote":null},{"number":28,"title":"Пять шагов автомата","question":"За один шаг автомат умеет выполнять одну из четырех операций: либо умножить данное число на 2, либо умножить данное число на 3, либо возвести его в квадрат, либо в куб. Что может получиться после 5 шагов, если начать с числа 15?","options":[{"text":"2⁸ · 3⁵ · 5⁶"},{"text":"2 · 3⁴ · 5²"},{"text":"2⁸ · 3⁴ · 5²"},{"text":"2 · 3² · 5⁶"},{"text":"2⁶ · 3⁶ · 5⁴"}],"condition":null,"answer":4,"points":5,"review":[{"title":"Решение","text":"Умножение на 2 или 3 добавляет единицу к соответствующему показателю, а возведение в квадрат удваивает все показатели."},{"title":"Проверка","text":"У варианта E верная последовательность такая: умножить на 2, возвести в квадрат, умножить на 6 за два шага (на 2 и на 3), затем снова возвести в квадрат. Показатели при 2, 3 и 5 меняются от (0, 1, 1) через (1, 1, 1), (2, 2, 2), (3, 2, 2), (3, 3, 2) до (6, 6, 4)."},{"title":"Ответ","text":"У A и D показатель при 5 равен 6. Для этого нужны квадрат и куб, которые умножают исходный показатель при 3 хотя бы на 6. У B одно возведение в квадрат, одна операция ×2 после него и не более двух операций ×3, поэтому пяти шагов не набирается. У C показатель при 5 требует одного квадрата. Чтобы показатель при 2 достиг 8, все четыре остальные операции должны быть умножениями на 2 перед квадратом. Тогда показатель при 3 равен 2 вместо 4."}],"keyNote":null},{"number":29,"title":"Линия из дуг на плитках","question":"Имеются одинаковые плитки кафеля с нарисованными на них дугами. Длина каждой дуги равна 1, а концы дуг – середины сторон плитки. Из 16 таких плиток надо сложить квадрат. Некоторые из дуг будут соединяться между собой, образуя более длинные кривые. Какова наибольшая возможная длина такой кривой?","options":[{"text":"18"},{"text":"20"},{"text":"21"},{"text":"22"},{"text":"24"}],"condition":{"src":"assets/grades-9-10/2007/task-29.svg","width":142,"height":144,"alt":"Квадратная плитка с двумя дугами. Одна соединяет середины верхней и левой сторон, другая — середины нижней и правой."},"answer":3,"points":5,"review":[{"title":"Решение","text":"На границе квадрата 16 концов дуг, поэтому есть восемь открытых кривых. Из них максимум четыре состоят из одной дуги, по одной в каждом углу. Все прочие открытые кривые имеют по меньшей мере две дуги."},{"title":"Проверка","text":"Если самая длинная кривая открыта, вне неё нужно не меньше 4 + 2 × 3 = 10 дуг. Если она замкнута, вне неё остаются все восемь открытых кривых, требующие не меньше 12 дуг. Из 32 дуг на одну кривую может уйти не больше 22."},{"title":"Ответ","text":"Обозначим плитку как в условии через 0, повёрнутую на 90° — через 1. Возьмём ряды 0001, 1100, 0011 и 1010. От верхней стороны второй плитки верхнего ряда идёт кривая из 22 дуг."}],"keyNote":null},{"number":30,"title":"Три отрезка из вершины A","question":"В равнобедренном треугольнике ABC с основанием AB = 1 биссектриса, высота и медиана, проведенные из вершины A, имеют длины b, h и m соответственно. Какое из следующих равенств возможно?","options":[{"text":"m = 0,7"},{"text":"b = 1,5"},{"text":"h = 1,1"},{"text":"b = 0,6"},{"text":"все варианты A – D невозможны"}],"condition":null,"answer":4,"points":5,"review":[{"title":"Решение","text":"Пусть C находится над серединой AB на высоте t, а длина боковой стороны s > 1/2. Высота из A равна t/s < 1. Медиана из A идёт в середину BC, её горизонтальная проекция равна 3/4. Поэтому m > 3/4."},{"title":"Проверка","text":"Для биссектрисы из A формула даёт b² = s(2s + 1)/(s + 1)². При s > 1/2 это значение больше 4/9, поскольку 9s(2s + 1) − 4(s + 1)² = (2s − 1)(7s + 4) > 0. Оно меньше 2, поскольку до 2(s + 1)² в числителе не хватает 3s + 2."},{"title":"Ответ","text":"Итак, 2/3 < b < √2. Ни 0,6, ни 1,5 для биссектрисы не подходят, как и указанные значения высоты и медианы."}],"keyNote":null}]}];
'use strict';

(() => {
  const archive = globalThis.KENGURU_ARCHIVE ??= {};
  const visual = globalThis.KenguruVisual;
  const cyrillicAnswers = 'АБВГД';

  function circleComparison(step, frame) {
    const outline = '#54877e';
    const fill = ['#347d75', '#43998c', '#60a99d', '#2e807c'];
    const ink = '#172e34';
    const radius = 43;
    const quarter = 'M0 0H43A43 43 0 0 0 0 -43Z';
    if (step === 1) {
      const opacity = .25 + .75 * visual.reveal(frame);
      return visual.svg(`<rect x="225" y="20" width="190" height="190" rx="3" fill="#f1f6ee" stroke="${outline}" stroke-width="2"/>
        <path d="M320 115H415A95 95 0 0 0 320 20Z" fill="${fill[0]}" opacity="${opacity}"/>
        <path d="M320 123V130M415 123V130M320 126H415" fill="none" stroke="${ink}" stroke-width="2"/>
        <text x="367.5" y="154" fill="${ink}" font-size="17" text-anchor="middle">радиус</text>`,
      'Радиус четверти круга равен половине стороны квадрата', '0 0 640 230', 'worked-scene');
    }
    if (step !== 2) return null;

    const far = radius;
    const offsets = [
      [[-far, far], [-far, -far], [far, -far], [far, far]],
      [[0, 0], [0, 0], [0, 0], [0, 0]],
      [[-far, 0], [-far, 0], [far, 0], [far, 0]],
      [[0, far], [-far, -far], [far, -far], [0, far]],
    ];
    const groups = offsets.map((pieces, index) => {
      const x = index % 2 === 0 ? 222 : 418;
      const y = index < 2 ? 95 : 254;
      const start = index * .38;
      const turn = index === 1 ? 0 : 180 * visual.reveal((frame - start) * 2.5);
      const remaining = 1 - visual.reveal((frame - start - 1.2) * 1.15);
      const paths = pieces.map(([dx, dy], piece) =>
        `<path d="${quarter}" fill="${fill[piece]}" stroke="#fffefa"
          stroke-width=".6" transform="translate(${x + dx * remaining} ${y + dy * remaining}) rotate(${90 * piece + turn})"/>`
      ).join('');
      return `<rect x="${x - radius}" y="${y - radius}" width="${radius * 2}" height="${radius * 2}"
        fill="#f1f6ee" stroke="${outline}" stroke-width="1.6"/>${paths}
        <text x="${x - 96}" y="${y + 6}" fill="${ink}" font-size="20" text-anchor="middle">${cyrillicAnswers[index]}</text>`;
    });
    return visual.svg(groups.join(''), 'Четыре четверти каждого рисунка складываются в целый круг',
      '102 0 432 348', 'worked-scene');
  }

  function shadeCells(step, frame) {
    if (step !== 2) return null;
    const alreadyShaded = [2, 4, 7, 9];
    const newlyShaded = [0, 1];
    const cells = Array.from({length: 12}, (_, index) => {
      const x = 90 + index % 4 * 42;
      const y = 20 + Math.floor(index / 4) * 42;
      const change = newlyShaded.indexOf(index);
      const opacity = alreadyShaded.includes(index) ? 1 : change < 0 ? 0 : visual.reveal(frame * 2 - change * .65);
      return `<rect x="${x}" y="${y}" width="42" height="42" fill="#fff"/>
        <rect x="${x}" y="${y}" width="42" height="42" fill="#202020" opacity="${opacity}"/>
        <rect x="${x}" y="${y}" width="42" height="42" fill="none" stroke="#202020" stroke-width="1.2"/>`;
    });
    return visual.svg(cells.join(''), 'В двух белых клетках верхней строки появляется чёрная заливка',
      '65 6 218 154', 'worked-scene');
  }

  const editions = [...(globalThis.KENGURU_GRADES_7_8 ?? []), ...(globalThis.KENGURU_JUNIOR_SENIOR ?? [])];
  for (const edition of editions) {
    const answerLetters = [...(edition.answerLetters ?? cyrillicAnswers)];
    const {id, year, label, grades, tasksUrl, answersUrl, solutionUrl, cards} = edition;
    const lessons = [];
    const scenes = [];

    for (const {number, title, question, questionNote, options, condition, answer, points, review, keyNote} of cards) {
      const hasReview = review.length > 0;
      const choiceImages = options.map(option => option.image);
      const choices = options.map(option => option.text ?? '');
      const answerLetter = answerLetters[answer];
      const steps = [['Условие', 'Условие задачи', '']];
      for (const [index, stage] of review.entries()) {
        const final = index === review.length - 1;
        steps.push([final ? 'Ответ' : 'Шаг ' + (index + 1), stage.title, stage.text]);
      }
      if (!hasReview) {
        steps.push(['Ответ', 'Проверка по ключу', keyNote ?? (answerLetter ? 'Правильный вариант — ' + answerLetter + '.' : 'Сверь решение с ответом в PDF.')]);
      }

      lessons.push({
        number, title, short: title, question, questionNote, points, answer, choices, choiceImages,
        choiceLayout: {condition, options}, conditionImage: condition?.src, conditionAlt: condition?.alt,
        hideIntroText: true, paperEdition: !hasReview, showCompletedStep: hasReview,
        officialValueKey: answer === null,
        steps,
      });

      const keyedAnswer = visual.answerScene({letter: answerLetter, value: choices[answer]});
      scenes.push((step, frame) => {
        if (!step) return '';
        if (!hasReview) return keyedAnswer;
        const stage = review[step - 1];
        const animation = id === '2026-7-8' && number === 1 ? circleComparison(step, frame)
          : id === '2017-2' && number === 6 ? shadeCells(step, frame) : null;
        return animation ?? (visual.workedScene(stage, frame)
          || (step === review.length ? keyedAnswer : ''));
      });
    }
    archive[id] = {id, year, label, grades, answerLetters, sources: {tasksUrl, answersUrl, solutionUrl}, lessons, scenes};
  }
})();

register((globalThis.KENGURU_ARCHIVE["2007-9-10"] ?? [].concat(globalThis.KENGURU_ARCHIVE[2007] ?? []).find(edition => edition.id === "2007-9-10")), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
